mapper.select:
SELECT m.*, b.base_name,
CASE
    WHEN m.target_type = 'pond' THEN COALESCE(po.pond_name, CONCAT('塘口#', m.target_id))
    WHEN m.target_type = 'cage' THEN COALESCE(ci.cage_name, CONCAT('网箱#', m.target_id))
    WHEN m.target_type = 'vsl' THEN COALESCE(vi.vsl_name, CONCAT('工船#', m.target_id))
    ELSE CONCAT(m.target_type, '#', m.target_id)
END AS target_name
FROM medication_record m
LEFT JOIN base_info b ON m.base_id = b.id
LEFT JOIN pond_info po ON m.target_id = po.id AND m.target_type = 'pond'
LEFT JOIN cage_info ci ON m.target_id = ci.id AND m.target_type = 'cage'
LEFT JOIN vsl_info vi ON m.target_id = vi.id AND m.target_type = 'vsl'

    AND m.base_id = #{query.baseId}
    AND m.target_id = #{query.targetId}
    AND m.target_type = #{query.targetType}
    AND m.drug_name LIKE CONCAT('%', #{query.drugName}, '%')
    AND m.source = #{query.source}
    AND m.verify_status = #{query.verifyStatus}
    AND action_time >= #{query.actionTimeStart}
    AND action_time <= #{query.actionTimeEnd}

ORDER BY m.action_time DESC
